            divergence_60m_check.pack(side=tk.LEFT, padx=(0, 10))
            divergence_15m_check = ttk.Checkbutton(divergence_frame, text="15分钟多头发散", variable=divergence_15m_var)
            divergence_15m_check.pack(side=tk.LEFT)
            # 可选条件标签页
