        # 创建持仓标签页(使用辅助函数)
        self._create_holding_tab(self.position_trading_notebook, "持仓", 1)
        # 创建持仓2、持仓3、持仓4、持仓历史股标签页
        self._create_holding_tab(self.position_trading_notebook, "龙头股", 2)
