    def ocr_paste_image(self):
        """从剪贴板粘贴图片并OCR识别"""
        try:
            # 检查pytesseract和PIL是否可用
            try:
                import pytesseract
                from PIL import Image, ImageGrab
            except ImportError:
                messagebox.showerror("错误", "pytesseract或PIL未安装,无法使用OCR功能\n\n请运行: pip install pytesseract pillow")
                return
            # 在新线程中执行
            thread = threading.Thread(target=self._ocr_paste_image_thread, daemon=True)
            thread.start()
        except Exception as e:
            messagebox.showerror("错误", f"粘贴图片失败: {e!s}")
    def _ocr_paste_image_thread(self):
        """从剪贴板粘贴图片并OCR识别线程"""
        try:
            import io

            import pytesseract
            from PIL import Image, ImageGrab
            # 自动检测Tesseract路径
            tesseract_path = self._auto_detect_tesseract_ocr()
            if tesseract_path:
                pytesseract.pytesseract.tesseract_cmd = tesseract_path
            self.root.after(0, lambda: self.ocr_tab_widget.insert(tk.END, "正在从剪贴板读取图片...\n"))
            self.root.after(0, lambda: self.ocr_tab_widget.see(tk.END))
            # 尝试从剪贴板读取图片
            image = None
            # 方法1: 使用win32clipboard (Windows)
            try:
                import win32clipboard
                win32clipboard.OpenClipboard()
                try:
                    if win32clipboard.IsClipboardFormatAvailable(win32clipboard.CF_DIB):
                        data = win32clipboard.GetClipboardData(win32clipboard.CF_DIB)
                        win32clipboard.CloseClipboard()
                        bmp_header = b'BM' + (len(data) + 14).to_bytes(4, 'little') + b'\x00\x00\x00\x00\x36\x00\x00\x00'
                        bmp_data = bmp_header + data
                        image = Image.open(io.BytesIO(bmp_data))
                except Exception:
                    try:
                        win32clipboard.CloseClipboard()
                    except:
                        pass
            except ImportError:
                pass
            except Exception:
                pass
            # 方法2: 使用PIL的ImageGrab
            if image is None:
                try:
                    image = ImageGrab.grabclipboard()
                except Exception:
                    pass
            # 检查是否成功获取图片
            if image is None or not isinstance(image, Image.Image):
                self.root.after(0, lambda: messagebox.showwarning("警告",
                    "剪贴板中没有图片!\n\n请先复制图片到剪贴板"))
                return
            # OCR识别
            self.root.after(0, lambda: self.ocr_tab_widget.insert(tk.END, "正在进行OCR识别...\n"))
            self.root.after(0, lambda: self.ocr_tab_widget.see(tk.END))
            ocr_result = pytesseract.image_to_string(image, lang='chi_sim+eng')
            if ocr_result.strip():
                result_text = f"\n{'='*80}\n"
                result_text += "来源: 剪贴板图片\n"
                result_text += f"时间: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n"
                result_text += f"{'='*80}\n"
                result_text += ocr_result.strip()
                result_text += "\n\n"
                # 显示在OCR识别器标签页
                self.root.after(0, lambda: self.ocr_tab_widget.insert(tk.END, result_text))
                self.root.after(0, lambda: self.ocr_tab_widget.see(tk.END))
                # 同时显示在分析标签页
                self.root.after(0, lambda: self.analysis_tab_widget.insert(tk.END, result_text))
                self.root.after(0, lambda: self.analysis_tab_widget.see(tk.END))
                self.root.after(0, lambda: messagebox.showinfo("成功",
                    f"OCR识别完成!\n\n识别字符数: {len(ocr_result)}\n识别结果已显示在分析标签页"))
            else:
                self.root.after(0, lambda: messagebox.showwarning("警告", "未识别到任何文字"))
        except Exception as e:
            self.root.after(0, lambda e=e: messagebox.showerror("错误", f"OCR识别失败: {e!s}"))
            import traceback
            traceback.print_exc()
    def ocr_recognize_ths(self):
        """同花顺识别:识别OCR结果中的同花顺数据并保存到数据库"""
        try:
            # 获取OCR识别结果
            ocr_text = self.ocr_tab_widget.get("1.0", tk.END).strip()
            if not ocr_text:
                messagebox.showwarning("警告", "请先进行OCR识别,识别结果中需要包含同花顺数据")
                return
            # 解析同花顺数据
            parsed_data = self._parse_ths_data(ocr_text)
            if not parsed_data:
                messagebox.showwarning("警告", "未能从OCR结果中识别到同花顺数据,请确保识别结果包含完整的同花顺表格数据")
                return
            # 显示识别结果并询问是否保存
            result_text = f"识别到 {len(parsed_data)} 条同花顺数据:\n\n"
            for idx, data in enumerate(parsed_data[:10], 1):  # 只显示前10条
                result_text += f"{idx}. {data.get('stock_code', '')} {data.get('stock_name', '')} "
                result_text += f"现价:{data.get('current_price', '')} 涨幅:{data.get('change_pct', '')}\n"
            if len(parsed_data) > 10:
                result_text += f"... 还有 {len(parsed_data) - 10} 条数据\n"
            if messagebox.askyesno("确认保存", f"{result_text}\n是否保存到数据库?"):
                saved_count = self._save_ths_data_to_db(parsed_data)
                if saved_count > 0:
                    # 显示自定义对话框,包含打开数据表按钮
                    self._show_ths_save_result_dialog("成功", f"已成功保存 {saved_count} 条同花顺数据到数据库", saved_count)
                else:
                    messagebox.showerror("失败", "未能保存任何数据到数据库")
        except Exception as e:
            messagebox.showerror("错误", f"同花顺识别失败: {e!s}")
            import traceback
            traceback.print_exc()
    def _parse_number(self, numbers, index):
        """解析数字,如果索引超出范围返回None"""
        try:
            if index < len(numbers):
                value = float(numbers[index])
                # 过滤明显不合理的大数字(可能是日期或时间)
                if abs(value) < 1e10:
                    return value
            return None
        except:
            return None
    def _parse_integer(self, numbers, index):
        """解析整数,如果索引超出范围返回None"""
        try:
            if index < len(numbers):
                value = int(float(numbers[index]))
                if abs(value) < 1e6:
                    return value
            return None
        except:
            return None
    def _perform_ocr_on_screenshot(self, image_path, name):
        """对截图进行OCR识别并返回结果文本"""
        try:
            import pytesseract
            from PIL import Image
            # 自动检测Tesseract路径
            tesseract_path = self._auto_detect_tesseract_ocr()
            if tesseract_path:
                pytesseract.pytesseract.tesseract_cmd = tesseract_path
            # 打开图片
            image = Image.open(image_path)
            # OCR识别(使用中文+英文)
            ocr_result = pytesseract.image_to_string(image, lang='chi_sim+eng')
            if ocr_result.strip():
                # 添加文件信息
                filename = os.path.basename(image_path)
                file_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                result_text = f"\n{'='*80}\n"
                result_text += f"来源: {name}\n"
                result_text += f"文件: {filename}\n"
                result_text += f"时间: {file_time}\n"
                result_text += f"{'='*80}\n"
                result_text += ocr_result.strip()
                result_text += "\n\n"
                return result_text
            else:
                return None
        except ImportError:
            # pytesseract未安装,返回None但不报错
            return None
        except Exception as e:
            # OCR识别失败,返回None但不中断截图流程
            print(f"OCR识别失败: {e}")
            return None
    def _auto_detect_tesseract_ocr(self):
        """自动检测Tesseract OCR路径"""
        import shutil
        # 检查环境变量PATH中的tesseract
        tesseract_cmd = shutil.which("tesseract")
        if tesseract_cmd:
            return tesseract_cmd
        # 常见安装路径(Windows)
        common_paths = [
            r"C:\Program Files\Tesseract-OCR\tesseract.exe",
            r"C:\Program Files (x86)\Tesseract-OCR\tesseract.exe",
            r"C:\Tesseract-OCR\tesseract.exe",
            r"D:\Program Files\Tesseract-OCR\tesseract.exe",
            r"D:\Tesseract-OCR\tesseract.exe",
        ]
        # 检查常见路径
        for path in common_paths:
            if os.path.exists(path):
                return path
        return None
    def close_result_tab(self, tab_id):
        """关闭指定的结果标签页"""
        if tab_id in self.result_tabs:
            tab_info = self.result_tabs[tab_id]
            self.result_notebook.forget(tab_info['frame'])
            del self.result_tabs[tab_id]
    def _configure_result_text_tags(self, text_widget):
        """配置结果文本框的颜色标签"""
        text_widget.tag_configure("five_day_daily", foreground="black", font=("TkDefaultFont", 16))
        text_widget.tag_configure("five_day_total", foreground="red", font=("TkDefaultFont", 17, "bold"))
        text_widget.tag_configure("ten_day_total", foreground="orange", font=("TkDefaultFont", 17, "bold"))
        text_widget.tag_configure("twenty_day_total", foreground="green", font=("TkDefaultFont", 17, "bold"))
        text_widget.tag_configure("sixty_day_total", foreground="purple", font=("TkDefaultFont", 17, "bold"))
        text_widget.tag_configure("positive", foreground="red", font=("TkDefaultFont", 16, "bold"))
        text_widget.tag_configure("negative", foreground="green", font=("TkDefaultFont", 16, "bold"))
        text_widget.tag_configure("error", foreground="red")
    def _refresh_clickable_links(self, text_widget):
        """刷新文本框中的链接高亮与双击打开范围。"""
        try:
            full_text = text_widget.get("1.0", tk.END)
            text_widget.tag_remove("hyperlink", "1.0", tk.END)
            for m in re.finditer(r"https?://[^\s<>\"]+", full_text):
                start_idx = f"1.0+{m.start()}c"
                end_idx = f"1.0+{m.end()}c"
                text_widget.tag_add("hyperlink", start_idx, end_idx)
        except Exception:
            pass
    def _enable_clickable_links(self, text_widget):
        """让文本框中的 URL 自动变蓝并支持双击打开。"""
        if getattr(text_widget, "_hyperlink_enabled", False):
            return
        text_widget._hyperlink_enabled = True
        text_widget.tag_configure("hyperlink", foreground="#1D4ED8", underline=True)
        def _open_link_on_double_click(event):
            idx = text_widget.index(f"@{event.x},{event.y}")
            for start, end in zip(text_widget.tag_ranges("hyperlink")[0::2], text_widget.tag_ranges("hyperlink")[1::2]):
                if text_widget.compare(idx, ">=", start) and text_widget.compare(idx, "<", end):
                    url = text_widget.get(start, end).strip()
                    if url:
                        webbrowser.open(url)
                    return "break"
            return None
        def _on_text_modified(_event=None):
            if getattr(text_widget, "_hyperlink_refreshing", False):
                return
            if not text_widget.edit_modified():
                return
            text_widget._hyperlink_refreshing = True
            try:
                self._refresh_clickable_links(text_widget)
            finally:
                text_widget.edit_modified(False)
                text_widget._hyperlink_refreshing = False
        text_widget.bind("<Double-Button-1>", _open_link_on_double_click, add="+")
        text_widget.bind("<<Modified>>", _on_text_modified, add="+")
        self._refresh_clickable_links(text_widget)
    def get_active_result_widget(self):
        """获取当前活动的结果标签页文本框"""
        try:
            selected_tab = self.result_notebook.select()
            if selected_tab:
                for tab_info in self.result_tabs.values():
                    if str(tab_info['frame']) == selected_tab:
                        return tab_info['widget']
        except:
            pass
        # 如果没有找到,返回第一个标签页
        if self.result_tabs:
            first_tab = next(iter(self.result_tabs.values()))
            return first_tab['widget']
        return None
    def _get_result_text_for_crawler(self):
        """获取用于爬虫输出的结果文本框(使用默认标签页)"""
        # 爬虫输出始终使用默认的"分析结果"标签页
        if self.result_tabs:
            # 查找"分析结果"标签页
            for tab_info in self.result_tabs.values():
                if tab_info['title'] == "分析结果":
                    return tab_info['widget']
            # 如果没有找到,返回第一个标签页
            first_tab = next(iter(self.result_tabs.values()))
            return first_tab['widget']
        return None
    def crawl_eastmoney_web(self):
        """自动爬取东方财富网页内容到左边新标签"""
        def crawl_thread():
            try:
                # 创建新标签页用于显示内容
                self.root.after(0, lambda: self.create_text_tab("东方财富"))
                # 更新结果文本框显示进度
                result_widget = self.get_active_result_widget()
                if result_widget:
                    self.root.after(0, lambda: result_widget.insert(tk.END, "正在爬取东方财富网页内容...\n"))
                    self.root.after(0, lambda: result_widget.see(tk.END))
                # 设置请求头
                headers = {
                    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                    'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
                    'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8',
                    'Accept-Encoding': 'gzip, deflate, br',
                    'Connection': 'keep-alive',
                    'Upgrade-Insecure-Requests': '1',
                    'Referer': 'https://www.eastmoney.com/'
                }
                # 爬取多个页面
                urls = [
                    "https://www.eastmoney.com/",
                    "https://quote.eastmoney.com/center/gridlist.html#hs_a_board",
                    "https://www.eastmoney.com/news/"
                ]
                all_content = []
                for url in urls:
                    try:
                        if result_widget:
                            self.root.after(0, lambda u=url: result_widget.insert(tk.END, f"正在访问: {u}\n"))
                            self.root.after(0, lambda: result_widget.see(tk.END))
                        response = requests.get(url, headers=headers, timeout=15)
                        if response.status_code == 200:
                            # 正确处理编码,避免乱码
                            if response.encoding is None or response.encoding == 'ISO-8859-1':
                                # 尝试从响应头或内容中检测编码
                                response.encoding = response.apparent_encoding
                            if not response.encoding or response.encoding.lower() not in ['utf-8', 'utf8']:
                                # 如果检测到的编码不是UTF-8,尝试使用UTF-8
                                try:
                                    response.encoding = 'utf-8'
                                except:
                                    pass
                            # 解析HTML内容
                            soup = BeautifulSoup(response.text, 'html.parser')
                            # 移除脚本和样式标签
                            for script in soup(["script", "style", "noscript"]):
                                script.decompose()
                            # 提取文本内容
                            text_content = soup.get_text(separator='\n', strip=True)
                            # 清理多余空白
                            lines = [line.strip() for line in text_content.split('\n') if line.strip()]
                            cleaned_text = '\n'.join(lines)
                            if cleaned_text:
                                all_content.append(f"\n{'='*50}\n来源: {url}\n{'='*50}\n{cleaned_text}\n")
                                if result_widget:
                                    self.root.after(0, lambda: result_widget.insert(tk.END, f"成功获取内容,长度: {len(cleaned_text)} 字符\n"))
                                    self.root.after(0, lambda: result_widget.see(tk.END))
                        else:
                            if result_widget:
                                self.root.after(0, lambda s=response.status_code: result_widget.insert(tk.END, f"HTTP状态码: {s}\n"))
                                self.root.after(0, lambda: result_widget.see(tk.END))
                        time.sleep(1)  # 延迟避免请求过快
                    except Exception as e:
                        if result_widget:
                            self.root.after(0, lambda err=str(e): result_widget.insert(tk.END, f"访问 {url} 失败: {err}\n"))
                            self.root.after(0, lambda: result_widget.see(tk.END))
                        continue
                # 将所有内容添加到文本框
                if all_content:
                    full_content = '\n'.join(all_content)
                    text_widget = self.get_active_text_widget()
                    if text_widget:
                        self.root.after(0, lambda: text_widget.insert("1.0", full_content))
                        self.root.after(0, lambda: text_widget.see("1.0"))
                    if result_widget:
                        self.root.after(0, lambda: result_widget.insert(tk.END, f"\n爬取完成!总共获取 {len(all_content)} 个页面的内容,总长度: {len(full_content)} 字符\n"))
                        self.root.after(0, lambda: result_widget.see(tk.END))
                else:
                    if result_widget:
                        self.root.after(0, lambda: result_widget.insert(tk.END, "\n未能获取到任何内容\n"))
                        self.root.after(0, lambda: result_widget.see(tk.END))
                    self.root.after(0, lambda: messagebox.showwarning("警告", "未能获取到网页内容"))
            except Exception as e:
                error_msg = f"爬取失败: {e!s}"
                if result_widget:
                    self.root.after(0, lambda: result_widget.insert(tk.END, f"\n{error_msg}\n"))
                    self.root.after(0, lambda: result_widget.see(tk.END))
                self.root.after(0, lambda: messagebox.showerror("错误", error_msg))
        # 在后台线程中执行
        threading.Thread(target=crawl_thread, daemon=True).start()
