                        index = selection[0]
                        old_sector = sector_list[index]
                        new_sector = simpledialog.askstring("编辑板块", "请输入新的板块名称:", initialvalue=old_sector)
                        if new_sector and new_sector.strip():
                            sector_list[index] = new_sector.strip()
                            load_sectors()
                            sector_combo['values'] = sector_list
