    def _build_crawler_buttons(self, row1, row2):
        """从配置文件构建爬取按钮"""
        # 清空现有按钮
        for widget in row1.winfo_children():
            widget.destroy()
        for widget in row2.winfo_children():
            widget.destroy()
        # 按排序字段排序
        sorted_config = sorted(self.crawler_config, key=lambda x: x.get("sort_order", 999))
        # 将按钮分配到两行;若 row1/row2 是同一容器,则合并为一行
        single_row_mode = (row1 == row2)
        for idx, item in enumerate(sorted_config):
            key = item.get("key", "")
            name = item.get("name", "")
            url = item.get("url", "")
            bg_color = item.get("bg_color", "lightgray")
            item.get("fg_color", "black")
            command_str = item.get("command", "")
            # 选择行(前3个在第一行,后面的在第二行)
            target_row = row1 if (single_row_mode or idx < 3) else row2
            # 创建复选框,加载保存的状态
            var = tk.BooleanVar(value=self.crawler_checkbox_states.get(key, False))
            self.crawler_checkboxes[key] = var
            checkbox = ttk.Checkbutton(target_row, variable=var,
                                      command=lambda k=key, v=var: self._save_crawler_checkbox_state(k, v.get()))
            checkbox.pack(side=tk.LEFT, padx=(0, 5))
            # 创建按钮
            def create_button_command(cmd_str, u=url):
                """创建按钮命令函数"""
                if cmd_str.startswith("run_crawler_script:"):
                    script_name = cmd_str.split(":")[1]
                    return lambda: self.run_crawler_script(script_name)
                elif cmd_str == "crawl_taoguba_direct":
                    return self.crawl_taoguba_direct
                elif cmd_str == "crawl_eastmoney_web":
                    return self.crawl_eastmoney_web
                elif cmd_str == "crawl_xueqiu_web":
                    return self.crawl_xueqiu_web
                elif cmd_str == "crawl_xuangubao_web":
                    return self.crawl_xuangubao_web
                elif cmd_str == "crawl_ths_web":
                    return self.crawl_ths_web
                else:
                    # 默认打开URL
                    return lambda: webbrowser.open(u)
            btn = tk.Button(
                target_row,
                text=name,
                command=create_button_command(command_str, url),
                width=15,
                bg=bg_color,
                fg="black",
                font=("TkDefaultFont", 11)
            )
            btn.pack(side=tk.LEFT, padx=(0, 5))
    def show_crawler_editor(self):
        """显示爬取按钮编辑窗口"""
        try:
            if hasattr(self, '_crawler_editor_window') and self._crawler_editor_window and self._crawler_editor_window.winfo_exists():
                self._crawler_editor_window.lift()
                self._crawler_editor_window.focus_force()
                return
        except Exception:
            self._crawler_editor_window = None
        win = self._toplevel(self.root)
        win.title("编辑爬取按钮")
        win.geometry("800x600")
        win.transient(self.root)
        self._crawler_editor_window = win
        # 创建表格
        columns = ("name", "url", "bg_color", "fg_color", "command")
        headings = ("名称", "URL", "背景色", "文字色", "命令")
        tree_frame = ttk.Frame(win, padding=10)
        tree_frame.pack(fill=tk.BOTH, expand=True)
        tree = ttk.Treeview(tree_frame, columns=columns, show="headings", height=12)
        tree.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar = ttk.Scrollbar(tree_frame, orient=tk.VERTICAL, command=tree.yview)
        tree.configure(yscrollcommand=scrollbar.set)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        for col, heading in zip(columns, headings):
            width = 150 if col == "url" else 120 if col == "command" else 100
            tree.heading(col, text=heading)
            tree.column(col, width=width, anchor=tk.W)
        # 编辑表单
        form_frame = ttk.LabelFrame(win, text="编辑", padding=10)
        form_frame.pack(fill=tk.X, padx=10, pady=10)
        name_var = tk.StringVar()
        url_var = tk.StringVar()
        bg_color_var = tk.StringVar()
        fg_color_var = tk.StringVar()
        command_var = tk.StringVar()
        ttk.Label(form_frame, text="名称:").grid(row=0, column=0, sticky="e", pady=5)
        ttk.Entry(form_frame, textvariable=name_var, width=30).grid(row=0, column=1, sticky="w", pady=5, padx=(5, 0))
        ttk.Label(form_frame, text="URL:").grid(row=1, column=0, sticky="e", pady=5)
        ttk.Entry(form_frame, textvariable=url_var, width=50).grid(row=1, column=1, sticky="w", pady=5, padx=(5, 0))
        # 颜色选择
        color_frame = ttk.Frame(form_frame)
        color_frame.grid(row=2, column=0, columnspan=2, sticky="ew", pady=5)
        ttk.Label(color_frame, text="背景色:").pack(side=tk.LEFT, padx=(0, 5))
        bg_color_entry = ttk.Entry(color_frame, textvariable=bg_color_var, width=15)
        bg_color_entry.pack(side=tk.LEFT, padx=(0, 10))
        def choose_bg_color():
            color = self._choose_color(bg_color_var.get() or "lightgray")
            if color:
                bg_color_var.set(color)
        ttk.Button(color_frame, text="选择", command=choose_bg_color, width=8).pack(side=tk.LEFT, padx=(0, 20))
        ttk.Label(color_frame, text="文字色:").pack(side=tk.LEFT, padx=(0, 5))
        fg_color_entry = ttk.Entry(color_frame, textvariable=fg_color_var, width=15)
        fg_color_entry.pack(side=tk.LEFT, padx=(0, 10))
        def choose_fg_color():
            color = self._choose_color(fg_color_var.get() or "black")
            if color:
                fg_color_var.set(color)
        ttk.Button(color_frame, text="选择", command=choose_fg_color, width=8).pack(side=tk.LEFT, padx=(0, 20))
        # 颜色预览
        color_preview = tk.Label(color_frame, text="预览", width=10, relief=tk.SUNKEN)
        color_preview.pack(side=tk.LEFT, padx=(20, 0))
        def update_color_preview(*args):
            bg = bg_color_var.get() or "lightgray"
            fg = fg_color_var.get() or "black"
            try:
                color_preview.config(bg=bg, fg=fg)
            except:
                pass
        bg_color_var.trace("w", update_color_preview)
        fg_color_var.trace("w", update_color_preview)
        update_color_preview()
        # 命令选择
        ttk.Label(form_frame, text="命令:").grid(row=3, column=0, sticky="e", pady=5)
        command_combo = ttk.Combobox(form_frame, textvariable=command_var, width=30, state="readonly")
        command_combo['values'] = (
            "crawl_taoguba_direct",
            "crawl_eastmoney_web",
            "crawl_xueqiu_web",
            "crawl_xuangubao_web",
            "crawl_ths_web",
            "run_crawler_script:jiuyan"
        )
        command_combo.grid(row=3, column=1, sticky="w", pady=5, padx=(5, 0))
        def refresh_tree():
            tree.delete(*tree.get_children())
            sorted_config = sorted(self.crawler_config, key=lambda x: x.get("sort_order", 999))
            for item in sorted_config:
                values = (
                    item.get("name", ""),
                    item.get("url", ""),
                    item.get("bg_color", ""),
                    item.get("fg_color", ""),
                    item.get("command", "")
                )
                tree.insert("", tk.END, values=values, tags=(item.get("key", ""),))
        def clear_form():
            name_var.set("")
            url_var.set("")
            bg_color_var.set("")
            fg_color_var.set("")
            command_var.set("")
        def get_selected_key():
            selection = tree.selection()
            if not selection:
                return None
            tags = tree.item(selection[0])['tags']
            return tags[0] if tags else None
        def on_tree_select(event):
            key = get_selected_key()
            if key:
                item = next((x for x in self.crawler_config if x.get("key") == key), None)
                if item:
                    name_var.set(item.get("name", ""))
                    url_var.set(item.get("url", ""))
                    bg_color_var.set(item.get("bg_color", ""))
                    fg_color_var.set(item.get("fg_color", ""))
                    command_var.set(item.get("command", ""))
        tree.bind("<<TreeviewSelect>>", on_tree_select)
        def add_entry():
            name = name_var.get().strip()
            url = url_var.get().strip()
            if not name or not url:
                messagebox.showwarning("提示", "请填写名称和URL")
                return
            # 生成唯一的key
            key = name.lower().replace("爬取", "").replace(" ", "_")
            # 确保key唯一
            existing_keys = {item.get("key") for item in self.crawler_config}
            counter = 1
            original_key = key
            while key in existing_keys:
                key = f"{original_key}_{counter}"
                counter += 1
            entry = {
                "key": key,
                "name": name,
                "url": url,
                "bg_color": bg_color_var.get().strip() or "lightgray",
                "fg_color": fg_color_var.get().strip() or "black",
                "command": command_var.get().strip() or "",
                "sort_order": len(self.crawler_config) + 1
            }
            self.crawler_config.append(entry)
            self.save_crawler_config()
            if hasattr(self, 'crawler_row1') and hasattr(self, 'crawler_row2'):
                self._build_crawler_buttons(self.crawler_row1, self.crawler_row2)
            refresh_tree()
            clear_form()
        def update_entry():
            key = get_selected_key()
            if not key:
                messagebox.showwarning("提示", "请选择需要修改的项")
                return
            item = next((x for x in self.crawler_config if x.get("key") == key), None)
            if not item:
                return
            name = name_var.get().strip()
            url = url_var.get().strip()
            if not name or not url:
                messagebox.showwarning("提示", "请填写名称和URL")
                return
            item["name"] = name
            item["url"] = url
            item["bg_color"] = bg_color_var.get().strip() or "lightgray"
            item["fg_color"] = fg_color_var.get().strip() or "black"
            item["command"] = command_var.get().strip() or ""
            self.save_crawler_config()
            if hasattr(self, 'crawler_row1') and hasattr(self, 'crawler_row2'):
                self._build_crawler_buttons(self.crawler_row1, self.crawler_row2)
            refresh_tree()
        def delete_entry():
            key = get_selected_key()
            if not key:
                messagebox.showwarning("提示", "请选择需要删除的项")
                return
            if messagebox.askyesno("确认", "确定要删除该按钮吗?"):
                self.crawler_config = [x for x in self.crawler_config if x.get("key") != key]
                self.save_crawler_config()
                if hasattr(self, 'crawler_row1') and hasattr(self, 'crawler_row2'):
                    self._build_crawler_buttons(self.crawler_row1, self.crawler_row2)
                refresh_tree()
                clear_form()
        button_frame = ttk.Frame(form_frame)
        button_frame.grid(row=4, column=0, columnspan=2, pady=(10, 0))
        ttk.Button(button_frame, text="新增", width=10, command=add_entry).pack(side=tk.LEFT, padx=4)
        ttk.Button(button_frame, text="更新", width=10, command=update_entry).pack(side=tk.LEFT, padx=4)
        ttk.Button(button_frame, text="删除", width=10, command=delete_entry).pack(side=tk.LEFT, padx=4)
        ttk.Button(button_frame, text="清空", width=10, command=clear_form).pack(side=tk.LEFT, padx=4)
        refresh_tree()
    def _open_market_link(self, url):
        """在浏览器中打开链接"""
        if not url:
            return
        try:
            webbrowser.open_new(url)
        except Exception as exc:
            messagebox.showerror("错误", f"无法打开链接: {exc}")
    def _handle_market_nav_click(self, name, url, desc=None):
        """打开链接并一键复制内容到新的文本标签页"""
        if not url:
            messagebox.showwarning("提示", "该导航暂未配置有效链接")
            return
        # 始终先在浏览器中打开
        self._open_market_link(url)
        if not hasattr(self, "_market_nav_fetching"):
            self._market_nav_fetching = set()
        if url in self._market_nav_fetching:
            print(f"正在抓取 {url},请稍候...")
            return
        self._market_nav_fetching.add(url)
        threading.Thread(
            target=self._fetch_market_nav_content,
            args=(name, url, desc),
            daemon=True
        ).start()
    def _fetch_market_nav_content(self, name, url, desc=None):
        """抓取市场导航链接内容并生成新的文本标签页"""
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
            'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
            'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8',
            'Accept-Encoding': 'gzip, deflate, br',
            'Connection': 'keep-alive',
            'Upgrade-Insecure-Requests': '1'
        }
        try:
            html_content, used_encoding = self._fetch_with_encoding_fix(url, headers, max_retries=1)
            if not html_content:
                raise ValueError("未能获取网页内容")
            soup = BeautifulSoup(html_content, 'html.parser')
            for script in soup(["script", "style", "noscript"]):
                script.decompose()
            text_content = soup.get_text(separator='\n', strip=True)
            lines = [line.strip() for line in text_content.split('\n') if line.strip()]
            cleaned_text = '\n'.join(lines).strip()
            if not cleaned_text:
                cleaned_text = "⚠️ 未提取到有效文本内容,可能需要手动复制。"
            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            meta_lines = [
                "=" * 80,
                f"来源: {name}",
                f"链接: {url}",
                f"抓取时间: {timestamp}"
            ]
            if desc:
                meta_lines.append(f"描述: {desc}")
            if used_encoding:
                meta_lines.append(f"编码: {used_encoding}")
            meta_lines.append("=" * 80)
            header_text = '\n'.join(meta_lines)
            tab_title = f"{name}{datetime.now().strftime('%H:%M')}"
            full_text = f"{header_text}\n\n{cleaned_text}"
            def create_tab():
                self.create_text_tab(tab_title, full_text)
            self.root.after(0, create_tab)
        except Exception as exc:
            print(f"抓取 {name} ({url}) 失败: {exc}")
        finally:
            if hasattr(self, "_market_nav_fetching"):
                self._market_nav_fetching.discard(url)
    def import_market_nav_data(self):
        """一键导入市场指数与热点导航配置"""
        try:
            raw_text = ""
            file_path = filedialog.askopenfilename(
                title="选择导航数据文件(JSON或文本)",
                filetypes=[("JSON Files", "*.json"), ("Text Files", "*.txt"), ("All Files", "*.*")]
            )
            if file_path:
                with open(file_path, "r", encoding="utf-8") as f:
                    raw_text = f.read()
            else:
                try:
                    raw_text = self.root.clipboard_get()
                    if not raw_text.strip():
                        raise ValueError("剪贴板为空")
                except Exception:
                    messagebox.showwarning("提示", "未选择文件,且剪贴板无有效内容。")
                    return
            parsed = self._parse_market_nav_import_data(raw_text)
            if not parsed or not any(parsed.values()):
                messagebox.showwarning(
                    "提示",
                    "未识别到有效的导航数据。\n支持 JSON 或按行 “类型|名称|链接|描述(可选)“ 的文本格式。"
                )
                return
            overwrite = messagebox.askyesno(
                "导入导航数据",
                "是否覆盖现有导航配置?\n选择“否“则在原有基础上追加。"
            )
            updated = False
            for key, items in parsed.items():
                if not items:
                    continue
                if overwrite:
                    self.market_nav_config[key] = self._deduplicate_nav_entries(items)
                else:
                    existing = self.market_nav_config.setdefault(key, [])
                    existing.extend(items)
                    self.market_nav_config[key] = self._deduplicate_nav_entries(existing)
                updated = True
            if not updated:
                messagebox.showinfo("提示", "没有可导入的有效数据。")
                return
            self.save_market_nav_config()
            self._build_market_nav_section(self.market_nav_container)
            messagebox.showinfo("成功", "导航数据已导入并生成。")
        except Exception as exc:
            messagebox.showerror("错误", f"导入导航数据失败: {exc}")
    def _open_search_engine(self, base_url, query):
        """根据查询词打开对应搜索引擎"""
        if not base_url:
            return
        query = (query or "").strip()
        # 修复乱码
        query = self._fix_encoding(query)
        url = base_url
        if "{query}" in base_url:
            try:
                from urllib.parse import quote_plus
                encoded = quote_plus(query) if query else ""
                url = base_url.format(query=encoded)
            except Exception:
                url = base_url.format(query=query)
        self._open_market_link(url)
        if query:
            self._add_search_history(query)
    def _open_ai_search(self, ai_site, query):
        """打开AI网站并进行搜索分析,结果复制到文本标签页"""
        if not query or not query.strip():
            messagebox.showwarning("提示", "请输入要搜索的关键词或问题")
            return
        query = query.strip()
        # 修复乱码
        query = self._fix_encoding(query)
        # 获取AI搜索URL(如果有的话,否则使用普通URL)
        search_url = ai_site.get("search_url", ai_site.get("url", ""))
        if "{query}" in search_url:
            try:
                from urllib.parse import quote_plus
                encoded = quote_plus(query) if query else ""
                url = search_url.format(query=encoded)
            except Exception:
                url = search_url.format(query=query)
        else:
            # 如果没有搜索URL,使用普通URL并打开
            url = ai_site.get("url", "")
            self._open_market_link(url)
            # 将查询内容复制到剪贴板,方便用户粘贴
            self.root.clipboard_clear()
            self.root.clipboard_append(query)
            self._safe_update()
            messagebox.showinfo("提示", f"已打开{ai_site['name']},查询内容已复制到剪贴板,请粘贴到AI工具中进行搜索和分析")
            if query:
                self._add_search_history(query)
            return
        # 打开AI搜索链接
        self._open_market_link(url)
        # 尝试抓取AI搜索结果并复制到文本标签页
        if not hasattr(self, "_market_nav_fetching"):
            self._market_nav_fetching = set()
        if url in self._market_nav_fetching:
            print(f"正在抓取 {url},请稍候...")
            return
        self._market_nav_fetching.add(url)
        threading.Thread(
            target=self._fetch_ai_search_result,
            args=(ai_site['name'], url, query),
            daemon=True
        ).start()
        if query:
            self._add_search_history(query)
    def _fetch_ai_search_result(self, ai_name, url, query):
        """抓取AI搜索结果并复制到文本标签页"""
        try:
            headers = {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
                'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8',
                'Accept-Encoding': 'gzip, deflate, br',
                'Connection': 'keep-alive',
                'Upgrade-Insecure-Requests': '1'
            }
            response = requests.get(url, headers=headers, timeout=15)
            response.raise_for_status()
            # 尝试多种编码
            html_content = None
            used_encoding = None
            for encoding in ['utf-8', 'gbk', 'gb2312', 'big5', response.apparent_encoding]:
                try:
                    if encoding:
                        html_content = response.content.decode(encoding)
                        used_encoding = encoding
                        break
                except (UnicodeDecodeError, LookupError):
                    continue
            if not html_content:
                raise ValueError("未能获取网页内容")
            # 修复乱码
            html_content = self._fix_encoding(html_content)
            soup = BeautifulSoup(html_content, 'html.parser')
            for script in soup(["script", "style", "noscript"]):
                script.decompose()
            text_content = soup.get_text(separator='\n', strip=True)
            lines = [line.strip() for line in text_content.split('\n') if line.strip()]
            cleaned_text = '\n'.join(lines).strip()
            # 修复乱码
            cleaned_text = self._fix_encoding(cleaned_text)
            if not cleaned_text:
                cleaned_text = f"⚠️ 未提取到有效文本内容。\n\n查询内容:{query}\n\n请手动在打开的AI网站中进行搜索和分析。"
            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            meta_lines = [
                "=" * 80,
                f"AI工具: {ai_name}",
                f"查询内容: {query}",
                f"链接: {url}",
                f"抓取时间: {timestamp}"
            ]
            if used_encoding:
                meta_lines.append(f"编码: {used_encoding}")
            meta_lines.append("=" * 80)
            header_text = '\n'.join(meta_lines)
            tab_title = f"{ai_name}_{datetime.now().strftime('%H:%M')}"
            full_text = f"{header_text}\n\n{cleaned_text}"
            # 修复乱码
            full_text = self._fix_encoding(full_text)
            def create_tab():
                self.create_text_tab(tab_title, full_text)
            self.root.after(0, create_tab)
        except Exception as exc:
            print(f"抓取AI搜索结果失败 {ai_name} ({url}): {exc}")
            # 即使抓取失败,也创建一个标签页提示用户
            def create_error_tab():
                error_text = f"AI搜索: {ai_name}\n查询: {query}\n链接: {url}\n\n⚠️ 无法自动抓取内容,请手动在打开的AI网站中进行搜索和分析。\n查询内容已复制到剪贴板。"
                self.root.clipboard_clear()
                self.root.clipboard_append(query)
                self._safe_update()
                self.create_text_tab(f"{ai_name}_搜索", error_text)
            self.root.after(0, create_error_tab)
        finally:
            if hasattr(self, "_market_nav_fetching"):
                self._market_nav_fetching.discard(url)
    def _fix_encoding(self, text):
        """修复文本乱码"""
        if not text:
            return text
        try:
            # 如果已经是字符串,尝试检测和修复
            if isinstance(text, str):
                # 尝试检测常见的乱码模式
                # 1. 检查是否包含乱码字符(如:锘?、等)
                if '\ufffd' in text or '锘?' in text[:10]:
                    # 尝试用不同编码重新解码
                    for encoding in ['gbk', 'gb2312', 'big5', 'latin1']:
                        try:
                            # 先编码再解码
                            text_bytes = text.encode('latin1', errors='ignore')
                            text = text_bytes.decode(encoding, errors='ignore')
                            break
                        except:
                            continue
                # 2. 修复常见的编码错误
                # 将常见的乱码字符替换
                replacements = {
                    '锘?': '',
                    '\ufffd': '',
                    '': '',
                }
                for old, new in replacements.items():
                    text = text.replace(old, new)
                return text
            else:
                return str(text)
        except Exception as e:
            print(f"修复乱码失败: {e}")
            return text if isinstance(text, str) else str(text)
    def _add_search_history(self, query):
        """记录最近搜索词并保存到配置文件"""
        if not query:
            return
        query = query.strip()
        if not query:
            return
        if not hasattr(self, "search_history"):
            self.search_history = []
        if query in self.search_history:
            self.search_history.remove(query)
        self.search_history.insert(0, query)
        self.search_history = self.search_history[:100]
        self._refresh_search_history_widget()
        # 保存到配置文件
        if not hasattr(self, "market_nav_config"):
            self.market_nav_config = self.load_market_nav_config()
        if "ai_search_questions" not in self.market_nav_config:
            self.market_nav_config["ai_search_questions"] = []
        questions = self.market_nav_config["ai_search_questions"]
        if query in questions:
            questions.remove(query)
        questions.insert(0, query)
        self.market_nav_config["ai_search_questions"] = questions[:100]  # 最多保存100条
        self.save_market_nav_config()
        # 刷新问题列表显示
        if hasattr(self, "ai_questions_listbox"):
            self._refresh_ai_questions_widget()
    def _refresh_search_history_widget(self):
        """刷新搜索记录显示"""
        if hasattr(self, "search_history_listbox") and self.search_history_listbox:
            self.search_history_listbox.delete(0, tk.END)
            for item in getattr(self, "search_history", []):
                self.search_history_listbox.insert(tk.END, item)
    def _refresh_ai_questions_widget(self):
        """刷新AI问题列表显示"""
        if hasattr(self, "ai_questions_listbox") and self.ai_questions_listbox:
            self.ai_questions_listbox.delete(0, tk.END)
            questions = self.market_nav_config.get("ai_search_questions", [])
            for item in questions:
                self.ai_questions_listbox.insert(tk.END, item)
    def _parse_market_nav_import_data(self, raw_text):
        """解析外部导航数据,返回规范化字典"""
        if not raw_text:
            return {}
        raw_text = raw_text.strip()
        if not raw_text:
            return {}
        # 1. 尝试 JSON
        try:
            data = json.loads(raw_text)
            normalized = self._normalize_market_nav_data(data)
            if normalized:
                return normalized
        except Exception:
            pass
        # 2. 逐行解析
        return self._parse_market_nav_lines(raw_text)
    def _normalize_market_nav_data(self, data):
        """将外部数据归一化为配置结构"""
        result = {"indices": [], "portals": [], "hot_sources": [], "dv_accounts": []}
        def normalize_entry(item, require_desc=False):
            if not isinstance(item, dict):
                return None
            name = item.get("name") or item.get("title")
            url = item.get("url") or item.get("link")
            if not name or not url:
                return None
            entry = {"name": name.strip(), "url": url.strip()}
            desc_val = item.get("desc") or item.get("description") or item.get("summary") or ""
            if require_desc or desc_val:
                entry["desc"] = desc_val.strip()
            return entry
        def append_items(key, items, require_desc=False):
            if not isinstance(items, list):
                return
            for item in items:
                entry = normalize_entry(item, require_desc=require_desc)
                if entry:
                    # 设置排序字段
                    entry["sort_order"] = len(result[key]) + 1
                    result[key].append(entry)
        if isinstance(data, dict):
            append_items("indices", data.get("indices") or data.get("index") or data.get("macro"), require_desc=True)
            append_items("portals", data.get("portals") or data.get("platforms") or data.get("sites"))
            append_items("hot_sources", data.get("hot_sources") or data.get("hot") or data.get("hotlists"))
            append_items("dv_accounts", data.get("dv_accounts") or data.get("dv") or data.get("kens"), require_desc=True)
            return result
        if isinstance(data, list):
            for item in data:
                if not isinstance(item, dict):
                    continue
                key = self._map_market_nav_category(item.get("type") or item.get("category"))
                if not key:
                    continue
                entry = normalize_entry(item, require_desc=(key == "indices"))
                if entry:
                    result[key].append(entry)
            return result
        return result
    def _parse_market_nav_lines(self, raw_text):
        """解析文本格式的导航数据"""
        result = {"indices": [], "portals": [], "hot_sources": [], "dv_accounts": []}
        lines = raw_text.splitlines()
        for line in lines:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if line.startswith("{") and line.endswith("}"):
                try:
                    item = json.loads(line)
                    key = self._map_market_nav_category(item.get("type") or item.get("category"))
                    if not key:
                        continue
                    entry = {
                        "name": item.get("name") or item.get("title"),
                        "url": item.get("url") or item.get("link"),
                        "desc": item.get("desc") or item.get("description") or ""
                    }
                    if entry["name"] and entry["url"]:
                        if not entry["desc"]:
                            entry.pop("desc")
                        # 设置排序字段
                        entry["sort_order"] = len(result[key]) + 1
                        result[key].append(entry)
                    continue
                except Exception:
                    pass
            parts = [p.strip() for p in re.split(r"[|,,]", line) if p.strip()]
            if len(parts) < 3:
                continue
            key = self._map_market_nav_category(parts[0])
            if not key:
                continue
            name = parts[1]
            url = parts[2]
            desc = parts[3] if len(parts) > 3 else ""
            if not name or not url:
                continue
            entry = {"name": name, "url": url}
            if desc:
                entry["desc"] = desc
            # 设置排序字段
            entry["sort_order"] = len(result[key]) + 1
            result[key].append(entry)
        return result
    def _map_market_nav_category(self, token):
        if not token:
            return None
        token = str(token).strip().lower()
        mapping = {
            "indices": "indices",
            "index": "indices",
            "macro": "indices",
            "指数": "indices",
            "宏观": "indices",
            "macro/index": "indices",
            "portal": "portals",
            "portals": "portals",
            "platform": "portals",
            "platforms": "portals",
            "site": "portals",
            "sites": "portals",
            "财经": "portals",
            "量化": "portals",
            "hot": "hot_sources",
            "hotlist": "hot_sources",
            "hot_sources": "hot_sources",
            "热门": "hot_sources",
            "榜单": "hot_sources",
            "dv": "dv_accounts",
            "dva": "dv_accounts",
            "大v": "dv_accounts",
            "公众号": "dv_accounts",
            "大v公众号": "dv_accounts",
            "opinion": "dv_accounts",
            "kol": "dv_accounts"
        }
        return mapping.get(token)
    def _deduplicate_nav_entries(self, items):
        seen = set()
        deduped = []
        for item in items:
            if not isinstance(item, dict):
                continue
            name = item.get("name")
            url = item.get("url")
            if not name or not url:
                continue
            key = (name.strip(), url.strip())
            if key in seen:
                continue
            seen.add(key)
            cleaned = {"name": name.strip(), "url": url.strip()}
            desc = item.get("desc")
            if desc:
                cleaned["desc"] = desc.strip()
            deduped.append(cleaned)
        return deduped
