    def _prediction_fetch_market_article_snippets(self, max_n=10, body_chars=900):
        """从东方财富财经列表页抓取多篇报道的标题、链接与正文摘要(供 AI 归纳观点与板块)。"""
        import re
        try:
            import requests
        except Exception:
            return []
        headers = {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
            "Accept-Language": "zh-CN,zh;q=0.9",
        }
        urls = []
        for lp in (
            "https://finance.eastmoney.com/a/cjjyw.html",
            "https://finance.eastmoney.com/a/czpnc.html",
        ):
            try:
                r = requests.get(lp, headers=headers, timeout=18)
                r.encoding = getattr(r, "apparent_encoding", None) or r.encoding or "utf-8"
                for u in re.findall(r"https://finance\.eastmoney\.com/a/\d+\.html", r.text):
                    if u not in urls:
                        urls.append(u)
                    if len(urls) >= max_n * 3:
                        break
            except Exception:
                continue
            if len(urls) >= max_n:
                break
        out = []
        for url in urls[:max_n]:
            try:
                rr = requests.get(url, headers=headers, timeout=14)
                rr.encoding = getattr(rr, "apparent_encoding", None) or rr.encoding or "utf-8"
                m = re.search(r"<title>([^<]+)</title>", rr.text, re.IGNORECASE)
                title = (m.group(1).strip() if m else url).replace("_东方财富网", "").replace("- 东方财富网", "").strip()
                body = re.sub(r"<script[\s\S]*?</script>", " ", rr.text, flags=re.IGNORECASE)
                body = re.sub(r"<style[\s\S]*?</style>", " ", body, flags=re.IGNORECASE)
                body = re.sub(r"<[^>]+>", " ", body)
                body = re.sub(r"\s+", " ", body).strip()[:body_chars]
                if len(body) < 80:
                    continue
                out.append({"title": title, "url": url, "snippet": body})
            except Exception:
                continue
        return out
    def show_stock_management_dialog(self):
        """弹出自选股管理窗口"""
        if hasattr(self, "_stock_mgmt_window") and self._stock_mgmt_window:
            if self._stock_mgmt_window.winfo_exists():
                self._stock_mgmt_window.deiconify()
                self._stock_mgmt_window.lift()
                return
            self._stock_mgmt_window = None
        dialog = self._toplevel(self.root)
        dialog.title("自选股管理")
        dialog.geometry("1400x720")
        dialog.transient(self.root)
        dialog.resizable(True, True)  # 允许调整大小
        dialog.minsize(1000, 600)  # 设置最小尺寸
        dialog.grab_set()
        self._stock_mgmt_window = dialog
        def on_close():
            if self._stock_mgmt_window:
                self._stock_mgmt_window.destroy()
            self._stock_mgmt_window = None
        dialog.protocol("WM_DELETE_WINDOW", on_close)
        container = ttk.Frame(dialog, padding=10)
        container.pack(fill=tk.BOTH, expand=True)
        self.build_stock_management_tab(container, as_tab=False)
    def show_tushare_skills_dialog(self):
        """Tushare 技能查询与调用(对话框):查询基础接口名 -> 调用并展示前几行结果。"""
        win = self._toplevel(self.root)
        win.title("Tushare 技能查询与调用")
        win.geometry("1000x700")
