    def _get_next_month_first_trade(self, pro):
        """下月第一个交易日"""
        import datetime as dt
        today = dt.date.today()
        if today.month == 12:
            next_m = dt.date(today.year + 1, 1, 1)
        else:
            next_m = dt.date(today.year, today.month + 1, 1)
        # 找下月的交易日
        cal = pro.trade_cal(exchange="SSE",
            start_date=next_m.strftime("%Y%m%d"),
            end_date=(next_m + dt.timedelta(days=10)).strftime("%Y%m%d"), is_open="1")
        if cal is not None and len(cal) > 0:
            return str(cal["cal_date"].iloc[0])
        return next_m.strftime("%Y%m%d")

    def _get_month_last_trade(self, pro):
        """本月最后一个交易日"""
        import datetime as dt
        today = dt.date.today()
        if today.month == 12:
            next_m = dt.date(today.year + 1, 1, 1)
        else:
            next_m = dt.date(today.year, today.month + 1, 1)
        cal = pro.trade_cal(exchange="SSE",
            start_date=(next_m - dt.timedelta(days=20)).strftime("%Y%m%d"),
            end_date=(next_m - dt.timedelta(days=1)).strftime("%Y%m%d"), is_open="1")
        if cal is not None and len(cal) > 0:
            return str(cal["cal_date"].iloc[-1])
        return (next_m - dt.timedelta(days=1)).strftime("%Y%m%d")

    def _etf20_quick_backtest(self, pro, current_results, trade_date):
        """简化回测: 跑最近2年的月度调仓模拟"""
        import datetime as dt
        import time

        import numpy as np

        # 拉3年日线 (每只一次API)
        etf_codes = [r["ts_code"] for r in current_results]
        all_data = {}
        for tsc in etf_codes:
            try:
                h = pro.fund_daily(ts_code=tsc,
                    start_date=(dt.date.today()-dt.timedelta(days=1100)).strftime("%Y%m%d"),
                    end_date=trade_date)
                if h is not None and len(h) > 100:
                    all_data[tsc] = h.sort_values("trade_date").reset_index(drop=True)
                time.sleep(0.3)
            except Exception:
                pass

        if len(all_data) < 4:
            return {"win_rate": None, "note": "历史数据不足, 跳过回测"}

        # 计算每只ETF在绿灯/非绿灯状态下的下月平均收益
        stats = {}
        for tsc, df in all_data.items():
            cl = df["close"].values.astype(float)
            dates = df["trade_date"].values

            monthly = []
            last_month = ""
            for i in range(20, len(cl)-20):
                d = str(dates[i])
                ym = d[:6]
                if ym != last_month:
                    last_month = ym
                    ma20 = float(np.mean(cl[i-20:i]))
                    pct20 = (cl[i] - cl[i-20]) / cl[i-20] * 100
                    green = pct20 > 0 and cl[i] > ma20
                    next_ret = (cl[i+20] - cl[i]) / cl[i] * 100 if i+20 < len(cl) else None
                    if next_ret is not None:
                        monthly.append({"date": d, "green": green, "next_ret": next_ret})

            if monthly:
                green_rets = [m["next_ret"] for m in monthly if m["green"]]
                red_rets = [m["next_ret"] for m in monthly if not m["green"]]
                stats[tsc] = {
                    "n_months": len(monthly),
                    "green_avg": float(np.mean(green_rets)) if green_rets else 0,
                    "red_avg": float(np.mean(red_rets)) if red_rets else 0,
                    "green_count": len(green_rets),
                    "red_count": len(red_rets),
                }

        all_monthly_green_rets = []
        all_monthly_red_rets = []
        for s in stats.values():
            all_monthly_green_rets.extend([s["green_avg"]]*s["green_count"])
            all_monthly_red_rets.extend([s["red_avg"]]*s["red_count"])

        return {
            "win_rate_green": float(sum(1 for r in all_monthly_green_rets if r > 0) / max(len(all_monthly_green_rets), 1) * 100),
            "avg_ret_green": float(np.mean(all_monthly_green_rets)) if all_monthly_green_rets else 0,
            "avg_ret_red": float(np.mean(all_monthly_red_rets)) if all_monthly_red_rets else 0,
            "stats_per_etf": stats,
            "note": "简化回测: 绿灯状态下月平均收益 vs 非绿灯状态",
        }

    def _show_etf20_popup(self):
        """🎯 ETF六军 弹窗入口 - 半小时缓存 + 加载窗 + 后台线程"""
        import threading
        import time
        _cache = getattr(self, "_etf20_cache", None)
        _now = time.time()
        if _cache and (_now - _cache.get("ts", 0)) < 1800:
            print("[ETF六军] ✅ 使用缓存")
            self._show_etf20_dialog(_cache["data"], from_cache=True, cache_age_s=int(_now - _cache["ts"]))
            return

        loading_win = tk.Toplevel(self.root)
        loading_win.title("🎯 ETF六军会师")
        loading_win.geometry("400x200")
        loading_win.configure(bg="#E8EAF6")
        loading_win.transient(self.root)
        loading_win.grab_set()
        tk.Label(loading_win, text="🔄 六军会师策略计算中...", bg="#E8EAF6",
                 font=("", 14, "bold")).pack(pady=30)
        tk.Label(loading_win, text="拉取7只ETF行情 + MA20 + 月度回测", bg="#E8EAF6",
                 font=("", 10), fg="#666").pack()

        holder = {"data": None, "error": None}
        def _bg():
            try:
                holder["data"] = self._run_etf20_analysis()
            except Exception as e:
                import traceback; traceback.print_exc()
                holder["error"] = str(e)

        threading.Thread(target=_bg, daemon=True).start()
        def _poll():
            if holder["data"] is not None or holder["error"] is not None:
                loading_win.destroy()
                if holder["error"]:
                    messagebox.showerror("错误", f"计算失败: {holder['error']}")
                else:
                    self._etf20_cache = {"ts": time.time(), "data": holder["data"]}
                    self._show_etf20_dialog(holder["data"])
            else:
                self.root.after(300, _poll)
        self.root.after(300, _poll)

