        from datetime import timedelta as _td
        _yesterday = (datetime.now() - _td(days=1)).strftime('%Y-%m-%d')
        _today = datetime.now().strftime('%Y-%m-%d')
        ttk.Label(news_ctrl, text="起始:").pack(side=tk.LEFT, padx=2)
