    def _calculate_ema(self, data, period):
        """计算EMA"""
        if len(data) < period:
            return np.zeros(len(data))
        ema = np.zeros(len(data))
        ema[period-1] = np.mean(data[:period])
        multiplier = 2 / (period + 1)
        for i in range(period, len(data)):
            ema[i] = data[i] * multiplier + ema[i-1] * (1 - multiplier)
        return ema
    def _calculate_ma(self, data, period):
        """计算MA"""
        if len(data) < period:
            return np.zeros(len(data))
        ma = np.zeros(len(data))
        ma[period-1:] = np.convolve(data, np.ones(period)/period, mode='valid')
        return ma
    def _calculate_wr(self, high, low, close, period):
        """计算WR"""
        if len(close) < period:
            return np.zeros(len(close))
        wr = np.zeros(len(close))
        for i in range(period-1, len(close)):
            h_n = np.max(high[i-period+1:i+1])
            l_n = np.min(low[i-period+1:i+1])
            if h_n == l_n:
                wr[i] = -50
            else:
                wr[i] = (h_n - close[i]) / (h_n - l_n) * (-100)
        return wr
    def _calculate_cci(self, high, low, close, period):
        """计算CCI"""
        if len(close) < period:
            return np.zeros(len(close))
        tp = (high + low + close) / 3
        cci = np.zeros(len(close))
        for i in range(period-1, len(close)):
            ma_tp = np.mean(tp[i-period+1:i+1])
            md = np.mean(np.abs(tp[i-period+1:i+1] - ma_tp))
            if md == 0:
                cci[i] = 0
            else:
                cci[i] = (tp[i] - ma_tp) / (0.015 * md)
        return cci
    def _calculate_obv(self, close, volume):
        """计算OBV"""
        obv = np.zeros(len(close))
        obv[0] = volume[0]
        for i in range(1, len(close)):
            if close[i] > close[i-1]:
                obv[i] = obv[i-1] + volume[i]
            elif close[i] < close[i-1]:
                obv[i] = obv[i-1] - volume[i]
            else:
                obv[i] = obv[i-1]
        return obv
    def _calculate_dmi(self, high, low, close, period):
        """计算DMI"""
        if len(close) < period + 1:
            return {'plus_di': np.zeros(len(close)), 'minus_di': np.zeros(len(close)), 'adx': np.zeros(len(close))}
        # 计算TR
        tr = np.zeros(len(close))
        tr[0] = high[0] - low[0]
        for i in range(1, len(close)):
            tr[i] = max(high[i] - low[i], abs(high[i] - close[i-1]), abs(low[i] - close[i-1]))
        # 计算+DM和-DM
        plus_dm = np.zeros(len(close))
        minus_dm = np.zeros(len(close))
        for i in range(1, len(close)):
            up_move = high[i] - high[i-1]
            down_move = low[i-1] - low[i]
            if up_move > down_move and up_move > 0:
                plus_dm[i] = up_move
            if down_move > up_move and down_move > 0:
                minus_dm[i] = down_move
        # 计算+DI和-DI
        plus_di = np.zeros(len(close))
        minus_di = np.zeros(len(close))
        atr = np.zeros(len(close))
        atr[period-1] = np.mean(tr[:period])
        for i in range(period, len(close)):
            atr[i] = (atr[i-1] * (period - 1) + tr[i]) / period
            plus_di[i] = (np.sum(plus_dm[i-period+1:i+1]) / atr[i]) * 100
            minus_di[i] = (np.sum(minus_dm[i-period+1:i+1]) / atr[i]) * 100
        # 计算ADX
        adx = np.zeros(len(close))
        dx = np.zeros(len(close))
        for i in range(period, len(close)):
            if plus_di[i] + minus_di[i] == 0:
                dx[i] = 0
            else:
                dx[i] = abs(plus_di[i] - minus_di[i]) / (plus_di[i] + minus_di[i]) * 100
        for i in range(period * 2 - 1, len(close)):
            adx[i] = np.mean(dx[i-period+1:i+1])
        return {'plus_di': plus_di, 'minus_di': minus_di, 'adx': adx}
    def _check_new_high(self, stock_code, days=60):
        """检查股票是否创新高"""
        try:
            kd = self._get_daily_kline_data_tushare(str(stock_code).zfill(6), days=days)
            if not kd:
                return False
            highs = kd['data']['最高'].values
            if len(highs) < 2:
                return False
            current_high = float(highs[-1])
            previous_highs = highs[:-1]
            return current_high > max(previous_highs)
        except Exception:
            return False
    def _ema_np(self, arr, span):
        """指数移动平均(pandas ewm,与常见行情软件可略有差异)。"""
        s = pd.Series(np.asarray(arr, dtype=float))
        return s.ewm(span=float(span), adjust=False).mean().values




    def _get_major_index_changes(self):
        """沪深300/中证500/科创50(用作科创30近似)当日涨跌幅,优先 Tushare。"""
        idx_map = {
            "沪深300": "000300.SH",
            "中证500": "000905.SH",
            "科创50(替代科创30)": "000688.SH",
        }
        out = {}
        end_date = datetime.now().strftime("%Y%m%d")
        start_date = (datetime.now() - timedelta(days=10)).strftime("%Y%m%d")
        if TS_AVAILABLE and (getattr(self, "ts_token", None) or TS_DEFAULT_TOKEN):
            try:
                self._ensure_tushare_client(self.ts_token or TS_DEFAULT_TOKEN)
                for name, ts_code in idx_map.items():
                    try:
                        df = self.ts_client.index_daily(ts_code=ts_code, start_date=start_date, end_date=end_date)
                        if df is None or df.empty:
                            continue
                        df = df.sort_values("trade_date").tail(2).reset_index(drop=True)
                        if len(df) >= 2:
                            prev_close = float(df.iloc[-2]["close"])
                            close = float(df.iloc[-1]["close"])
                            pct = (close / prev_close - 1.0) * 100.0 if prev_close > 0 else 0.0
                            out[name] = {"close": close, "pct": pct, "source": "Tushare"}
                    except Exception:
                        continue
            except Exception:
                pass
        return out
