    def _query_neodata_safe(self, query, data_type="api", retries=3, interval=1.5):
        """T1: 统一 neodata 数据客户端(含重试 + 结构化错误)"""
        import time as _time
        for attempt in range(retries):
            try:
                query_neodata = None
                neodata_paths = [
                    os.path.expanduser("~/.qclaw/skills/neodata-financial-search"),
                    os.path.expanduser("~/Library/Application Support/QClaw/skills/neodata-financial-search"),
                ]
                for p in neodata_paths:
                    if os.path.isdir(p) and p not in sys.path:
                        sys.path.insert(0, p)
                        try:
                            from query import query_neodata as _qn
                            query_neodata = _qn
                            break
                        except ImportError:
                            sys.path.pop(0)
                            continue
                if query_neodata is None:
                    return {"error": "neodata模块未找到", "query": query}
                result = query_neodata(query, data_type)
                if result and not str(result).startswith("错误"):
                    return {"data": result, "query": query, "attempt": attempt + 1}
                if attempt < retries - 1:
                    _time.sleep(interval)
            except Exception as e:
                if attempt < retries - 1:
                    _time.sleep(interval)
                    continue
                return {"error": str(e), "query": query, "attempt": attempt + 1}
        return {"error": f"重试{retries}次后仍失败", "query": query}
    def _neodata_get_stock_ma(self, stock_code, periods=(5, 10, 20, 60)):
        """T1辅助: 通过 neodata 查询股票均线数据"""
        ma_str = "/".join([f"MA{p}" for p in periods])
        result = self._query_neodata_safe(f"{stock_code} 近60日K线行情 收盘价 {ma_str}")
        return result.get("data") if "error" not in result else None
    def _neodata_get_fundamental(self, stock_code):
        """T1辅助: 通过 neodata 查询基本面数据"""
        result = self._query_neodata_safe(f"{stock_code} 市值 营收增长率 机构持股比例 PE PB ROE")
        return result.get("data") if "error" not in result else None
    def _risk_filter_stock(self, stock_code, stock_name="", kline_data=None, fundamental=None):
        """T5: 全局风控过滤器"""
        result = {"pass": True, "reasons": [], "warnings": []}
        try:
            close_price = None
            if kline_data and kline_data.get('data') is not None:
                df = kline_data['data']
                if len(df) > 0:
                    close_price = float(df['收盘'].values[-1])
            if close_price is not None and close_price < 20:
                result["pass"] = False
                result["reasons"].append(f"股价{close_price:.2f}元<20元,不满足硬标准")
            if kline_data and kline_data.get('data') is not None:
                df = kline_data['data']
                if len(df) >= 60:
                    closes = df['收盘'].values
                    pct_change = (closes[-1] / closes[-60] - 1) * 100
                    if pct_change > 100:
                        result["pass"] = False
                        result["reasons"].append(f"近60日涨幅{pct_change:.1f}%>100%,回避")
                    elif pct_change > 50:
                        result["warnings"].append(f"近60日涨幅{pct_change:.1f}%较高,注意风险")
            if kline_data and kline_data.get('data') is not None:
                p_phase = self._p_phase_classify(kline_data)
                if p_phase.get("phase") == "P3":
                    result["pass"] = False
                    result["reasons"].append("P3狂热期(出货区),不碰")
                elif p_phase.get("phase") == "P0":
                    result["warnings"].append("P0衰退期,需谨慎")
            if fundamental and isinstance(fundamental, dict):
                market_cap = fundamental.get("market_cap", 0)
                if market_cap and market_cap < 100e8:
                    result["warnings"].append(f"市值{market_cap/1e8:.0f}亿<100亿,偏小盘")
                revenue_growth = fundamental.get("revenue_growth", 0)
                if revenue_growth and revenue_growth < 15:
                    result["warnings"].append(f"营收增长{revenue_growth:.1f}%<15%")
        except Exception as e:
            result["warnings"].append(f"风控检查异常: {e}")
        return result
    def _duanji_score(self, stock_code, kline_data=None, fundamental=None):
        """T2-DJ: 段基(段永平)7维基本面评分系统,总分105"""
        scores = {"商业模式": 0, "盈利质量": 0, "成长性": 0, "现金流": 0, "安全边际": 0, "护城河": 0, "估值": 0}
        details = {}
        try:
            if kline_data and kline_data.get('data') is not None:
                df = kline_data['data']
                if len(df) > 0:
                    close_price = float(df['收盘'].values[-1])
                    if len(df) >= 20:
                        closes = df['收盘'].values
                        ret_20d = (closes[-1] / closes[-20] - 1) * 100
                        scores["成长性"] = 12 if ret_20d > 10 else (8 if ret_20d > 0 else 4)
                        details["近20日涨幅"] = f"{ret_20d:.1f}%"
                    if len(df) >= 20:
                        vols = df['成交量'].values[-20:]
                        vol_cv = float(np.std(vols) / (np.mean(vols) + 1e-9))
                        scores["现金流"] = 12 if vol_cv < 0.5 else (8 if vol_cv < 1.0 else 4)
                        details["量能波动率"] = f"{vol_cv:.2f}"
                    if len(df) >= 60:
                        closes = df['收盘'].values
                        mean_60 = float(np.mean(closes[-60:]))
                        deviation = (close_price / mean_60 - 1) * 100
                        scores["安全边际"] = 13 if deviation < -5 else (10 if deviation < 0 else (7 if deviation < 10 else 3))
                        details["偏离60日均值"] = f"{deviation:.1f}%"
                    if 'ma_values' in kline_data:
                        ma20 = kline_data['ma_values'].get('ma20', [])
                        if ma20 and len(ma20) > 0:
                            ma20_val = float(ma20[-1])
                            pe_proxy = close_price / ma20_val
                            scores["估值"] = 13 if pe_proxy < 0.95 else (10 if pe_proxy < 1.05 else (6 if pe_proxy < 1.15 else 3))
                            details["价格/MA20"] = f"{pe_proxy:.2f}"
            if fundamental and isinstance(fundamental, dict):
                roe = fundamental.get("roe", 0)
                if roe:
                    scores["盈利质量"] = 14 if roe > 20 else (10 if roe > 10 else 5)
                    details["ROE"] = f"{roe:.1f}%"
                rev_growth = fundamental.get("revenue_growth", 0)
                if rev_growth and rev_growth > 20:
                    scores["成长性"] = max(scores["成长性"], 13)
                inst_hold = fundamental.get("institutional_holding", 0)
                if inst_hold:
                    scores["护城河"] = 14 if inst_hold > 50 else (10 if inst_hold > 30 else 5)
                    scores["商业模式"] = 12 if inst_hold > 50 else (9 if inst_hold > 30 else 6)
                    details["机构持仓"] = f"{inst_hold:.1f}%"
            for k in scores:
                if scores[k] == 0:
                    scores[k] = 7
        except Exception:
            pass
        total = sum(scores.values())
        verdict = "优秀(值得深入研究)" if total >= 80 else ("良好(可关注)" if total >= 65 else ("一般(需谨慎)" if total >= 50 else "较差(建议回避)"))
        return {"total": total, "max": 105, "scores": scores, "verdict": verdict, "details": details}
    def _munger_5pct_scan(self, stock_code, kline_data=None, market_data=None):
        """T2-MG: 芒格5%机会扫描器(大周期反转)"""
        result = {"triggered": False, "group": "", "signal": "", "details": {}}
        try:
            if kline_data and kline_data.get('data') is not None:
                df = kline_data['data']
                if len(df) >= 20:
                    closes = df['收盘'].values
                    ret_20d = (closes[-1] / closes[-20] - 1) * 100
                    ret_5d = (closes[-1] / closes[-5] - 1) * 100 if len(closes) >= 5 else 0
                    result["details"]["近5日跌幅"] = f"{ret_5d:.1f}%"
                    result["details"]["近20日跌幅"] = f"{ret_20d:.1f}%"
                    if ret_20d < -40:
                        result.update({"triggered": True, "group": "D-极端恐慌", "signal": "🔴极端恐慌,大周期反转机会"})
                    elif ret_20d < -20:
                        result.update({"triggered": True, "group": "C-个股超跌", "signal": "🟡个股超跌>20%,关注反弹"})
                    elif ret_5d < -10:
                        result.update({"triggered": True, "group": "C-短期超跌", "signal": "🟡短期超跌,观察支撑"})
            if market_data and isinstance(market_data, dict):
                up_count = market_data.get("up_count", 0)
                if up_count and up_count < 800:
                    result.update({"triggered": True, "group": "A-大盘恐慌", "signal": "🔴大盘恐慌(上涨<800),系统性机会"})
        except Exception as e:
            result["details"]["error"] = str(e)
        return result
    def _p_phase_classify(self, kline_data):
        """T2-PP: P阶段分类(P0衰退/P1低估/P2改善/P3狂热)"""
        result = {"phase": "P1", "score": {}, "description": ""}
        try:
            if kline_data and kline_data.get('data') is not None:
                df = kline_data['data']
                closes = df['收盘'].values
                vols = df['成交量'].values
                n = len(closes)
                if n < 20:
                    return result
                ma20 = float(np.mean(closes[-20:])) if n >= 20 else float(np.mean(closes))
                ma60 = float(np.mean(closes[-60:])) if n >= 60 else ma20
                close = float(closes[-1])
                val_score = 2 if close < ma20 * 0.95 else (1 if close < ma20 * 1.05 else (4 if close > ma60 * 1.15 else 3))
                ret_20d = (closes[-1] / closes[-20] - 1) * 100 if n >= 20 else 0
                fund_score = 2 if ret_20d < -10 else (3 if ret_20d < 5 else (4 if ret_20d < 20 else 5))
                vol_ratio = float(vols[-1] / (np.mean(vols[-20:]) + 1e-9)) if n >= 20 else 1.0
                deviation = abs(close / ma20 - 1) * 100
                emo_score = 1 if (vol_ratio < 0.8 and deviation < 3) else (2 if vol_ratio < 1.2 else (3 if vol_ratio < 2.0 else (4 if vol_ratio < 3.0 else 5)))
                result["score"] = {"估值": val_score, "基本面": fund_score, "情绪": emo_score, "近20日涨跌": f"{ret_20d:.1f}%", "量比": f"{vol_ratio:.2f}"}
                total = val_score + fund_score + emo_score
                if total <= 5:
                    result.update({"phase": "P0", "description": "衰退期(估值低+基本面差+情绪冰点)"})
                elif total <= 8:
                    result.update({"phase": "P1", "description": "低估期(估值偏低+基本面待改善)"})
                elif total <= 11:
                    result.update({"phase": "P2", "description": "改善期(估值合理+基本面向好+情绪活跃)"})
                else:
                    result.update({"phase": "P3", "description": "狂热期(估值高+涨幅大+情绪亢奋,出货区)"})
        except Exception:
            pass
        return result
    def _elevator_signal(self, kline_data):
        """T2-ZT: 坐电梯指标(通达信上下电梯)"""
        result = {"signal": "无", "fast": 0.0, "slow": 0.0, "action": "观望"}
        try:
            if kline_data and kline_data.get('data') is not None:
                df = kline_data['data']
                closes = df['收盘'].values
                n = len(closes)
                if n < 12:
                    return result
                N = 9
                ema = np.zeros(n)
                k = 2 / (N + 1)
                ema[0] = closes[0]
                for i in range(1, n):
                    ema[i] = closes[i] * k + ema[i-1] * (1 - k)
                if n >= 7:
                    ref_up = (ema[1:] > ema[:-1]).astype(float)
                    fast = np.sum(ref_up[-3:]) / 3 * 100
                    slow = np.sum(ref_up[-6:]) / 6 * 100
                    result["fast"] = float(fast)
                    result["slow"] = float(slow)
                    if n >= 8:
                        fast_prev = np.sum(ref_up[-4:-1]) / 3 * 100
                        slow_prev = np.sum(ref_up[-7:-1]) / 6 * 100
                        if fast > slow and fast_prev <= slow_prev:
                            result.update({"signal": "金叉", "action": "低买/进场"})
                        elif fast < slow and fast_prev >= slow_prev:
                            result.update({"signal": "死叉", "action": "高卖/出场"})
                        elif fast > slow:
                            result.update({"signal": "多头", "action": "持有"})
                        else:
                            result.update({"signal": "空头", "action": "观望"})
        except Exception:
            pass
        return result
    def _save_engine_report(self, stock_var, result_text, win):
        """保存引擎分析报告"""
        import re
        raw = stock_var.get().strip()
        stock_code = ""
        stock_name = raw
        m = re.search(r"(\d{6})", raw)
        if m:
            stock_code = m.group(1)
            stock_name = raw.replace(stock_code, "").replace("(", "").replace(")", "").strip()
        text = result_text.get("1.0", tk.END).strip()
        if not text:
            messagebox.showinfo("提示", "报告为空", parent=win)
            return
        filepath = self._save_analysis_report(stock_code, stock_name, text, "统一分析引擎")
        if filepath:
            messagebox.showinfo("成功", f"报告已保存:\n{filepath}", parent=win)
    # ==================== 通用技术指标(加仓skill复用) ====================
    # ==================== 分时背离检测(做T辅助) ====================
    @staticmethod
    def _find_local_extrema(arr, window=3):
        """
        手动滑窗找局部波峰/波谷。
        返回 (peaks, troughs),每个是 [(index, value), ...] 按时间升序。
        window 至少 3,越大越"严格"(波峰/波谷之间需要至少 window 个点)。
        """
        import numpy as np
        arr = np.array(arr, dtype=float)
        n = len(arr)
        if n < window * 2 + 1:
            return [], []
        peaks = []
        troughs = []
        half = window // 2
        for i in range(half, n - half):
            left = arr[i - half:i]
            right = arr[i + 1:i + 1 + half]
            v = arr[i]
            if v > left.max() and v > right.max():
                peaks.append((i, v))
            elif v < left.min() and v < right.min():
                troughs.append((i, v))
        return peaks, troughs
    def _detect_divergence(self, prices, dif_arr, window=5, min_price_pct=0.0015, min_dif_diff=0.0):
        """
        检测价格-DIF 背离。
        window: 极值窗口(越大越严格)
        min_price_pct: 峰/谷之间最小价格变动百分比(默认0.15%,过滤噪音)
        min_dif_diff: DIF 差异最小值(绝对值)
        返回列表: [{'type': 'top'/'bottom', 'price1': ..., 'price2': ...,
                    'dif1': ..., 'dif2': ..., 'idx1': ..., 'idx2': ..., 'trigger_idx': ...,
                    'price_pct': ..., 'dif_diff': ...}, ...]
        """
        import numpy as np
        prices = np.array(prices, dtype=float)
        dif_arr = np.array(dif_arr, dtype=float)
        peaks, troughs = self._find_local_extrema(prices, window=window)
        results = []
        # 顶背离:价格波峰1→波峰2更高,但 DIF 更低 → 适合卖
        for i in range(len(peaks) - 1):
            idx1, p1 = peaks[i]
            idx2, p2 = peaks[i + 1]
            d1 = dif_arr[idx1]
            d2 = dif_arr[idx2]
            # 价格创新高 + DIF 降低 → 顶背离
            if p2 > p1 and d2 < d1:
                price_pct = (p2 - p1) / p1
                dif_diff = abs(d2 - d1)
                # 幅度过滤
                if price_pct < min_price_pct and dif_diff < min_dif_diff + 0.01:
                    continue
                results.append({
                    "type": "top",
                    "label": "顶背离",
                    "advice": "适合卖出(做T高抛)",
                    "price1": float(p1), "price2": float(p2),
                    "dif1": float(d1), "dif2": float(d2),
                    "idx1": idx1, "idx2": idx2,
                    "trigger_idx": idx2,
                    "price_pct": float(price_pct * 100),
                    "dif_diff": float(dif_diff),
                })
        # 底背离:价格波谷1→波谷2更低,但 DIF 更高 → 适合买
        for i in range(len(troughs) - 1):
            idx1, p1 = troughs[i]
            idx2, p2 = troughs[i + 1]
            d1 = dif_arr[idx1]
            d2 = dif_arr[idx2]
            # 价格创新低 + DIF 抬高 → 底背离
            if p2 < p1 and d2 > d1:
                price_pct = abs(p2 - p1) / p1
                dif_diff = abs(d2 - d1)
                if price_pct < min_price_pct and dif_diff < min_dif_diff + 0.01:
                    continue
                results.append({
                    "type": "bottom",
                    "label": "底背离",
                    "advice": "适合买入(做T低吸)",
                    "price1": float(p1), "price2": float(p2),
                    "dif1": float(d1), "dif2": float(d2),
                    "idx1": idx1, "idx2": idx2,
                    "trigger_idx": idx2,
                    "price_pct": float(price_pct * 100),
                    "dif_diff": float(dif_diff),
                })
        # 过滤过近的背离(idx差太小)
        filtered = []
        last_idx = -1000
        for r in results:
            if r["idx2"] - last_idx >= window * 2:
                filtered.append(r)
                last_idx = r["idx2"]
        # 按时间排序
        filtered.sort(key=lambda r: r["trigger_idx"])
        return filtered
    def _fetch_index_min_data(self, symbol, name, max_lookback_days=10):
        """
        获取指数1分钟分时数据。非交易时段自动往前推最近交易日。
        symbol: '000001'(上证), '399001'(深成), '399006'(创业板)
        返回 dict: {'times': [...], 'prices': [...], 'volumes': [...], 'name': name, 'date': 'YYYYMMDD'}
        """
        import numpy as np
        try:
            if not AKSHARE_AVAILABLE:
                return None
            # 依次尝试今天、昨天、... 最多 max_lookback_days 天
            from datetime import datetime, timedelta

            import akshare as ak
            last_df = None
            last_date_str = None
            for offset in range(max_lookback_days):
                d = datetime.now() - timedelta(days=offset)
                ds = d.strftime("%Y%m%d")
                try:
                    df = ak.index_zh_a_hist_min_em(
                        symbol=symbol,
                        period="1",
                        start_date=ds + " 09:25:00",
                        end_date=ds + " 15:05:00",
                    )
                except Exception:
                    try:
                        df = ak.index_zh_a_hist_min_em(
                            symbol=symbol, period="1")
                        # 如果拿到的是"今天或最近"的全部数据,截取对应日期
                        if df is not None and len(df) > 0:
                            time_col_candidates = ["时间", "日期时间", "datetime", "date_time"]
                            for tc in time_col_candidates:
                                if tc in df.columns:
                                    try:
                                        mask = df[tc].astype(str).str.startswith(ds[:4] + "-" + ds[4:6] + "-" + ds[6:8])
                                        df = df[mask]
                                    except Exception:
                                        pass
                                    break
                    except Exception:
                        df = None
                if df is not None and len(df) >= 30:
                    last_df = df
                    last_date_str = ds
                    # 如果是今天,继续尝试取更早的;如果是历史日期,取到就停
                    if offset == 0:
                        # 今天拿到了,优先用今天
                        break
                    else:
                        # 历史日期拿到了也 break
                        break
            if last_df is None or len(last_df) < 30:
                return None
            df = last_df
            fetch_date = last_date_str or datetime.now().strftime("%Y%m%d")
            # 统一列名(不同版本可能叫 时间/日期/分钟)
            time_col = None
            for c in df.columns:
                if c in ("时间", "日期时间", "datetime", "date_time", "时间戳"):
                    time_col = c
                    break
            if time_col is None:
                for c in df.columns:
                    if "时间" in c or "time" in c.lower():
                        time_col = c
                        break
            price_col = None
            for c in ("收盘", "close", "收盘价", "Close"):
                if c in df.columns:
                    price_col = c
                    break
            if price_col is None:
                for c in df.columns:
                    if "收盘" in c or "close" in c.lower():
                        price_col = c
                        break
            vol_col = None
            for c in ("成交量", "volume", "Volume"):
                if c in df.columns:
                    vol_col = c
                    break
            if time_col is None or price_col is None:
                return None
            times = df[time_col].astype(str).tolist()
            prices = df[price_col].astype(float).tolist()
            volumes = df[vol_col].astype(float).tolist() if vol_col else [0] * len(prices)
            # 过滤非交易时间(午休 11:30-13:00)
            filtered_times, filtered_prices, filtered_vols = [], [], []
            for t, p, v in zip(times, prices, volumes):
                # 解析出小时分钟
                try:
                    t_str = str(t)
                    # 可能格式 "2026-08-28 10:31:00" 或 "10:31"
                    if " " in t_str:
                        hm = t_str.split(" ")[1]
                    else:
                        hm = t_str
                    h = int(hm.split(":")[0])
                    m = int(hm.split(":")[1]) if ":" in hm else 0
                    minutes = h * 60 + m
                    # 过滤午休 11:30 ~ 13:00
                    if 11 * 60 + 30 <= minutes < 13 * 60:
                        continue
                    # 只保留 9:30~11:30, 13:00~15:00
                    if not (9 * 60 + 30 <= minutes <= 15 * 60):
                        continue
                except Exception:
                    pass
                filtered_times.append(t)
                filtered_prices.append(p)
                filtered_vols.append(v)
            if len(filtered_prices) < 30:
                return None
            return {
                "name": name,
                "symbol": symbol,
                "times": filtered_times,
                "prices": np.array(filtered_prices),
                "volumes": np.array(filtered_vols),
                "date": fetch_date,
            }
        except Exception as e:
            print(f"[{name}] 分时数据获取失败: {e}")
            return None
