        report_menu.add_command(label="清空", command=lambda: report_txt.delete("1.0", tk.END))
        def _show_menu(e):
            try: report_menu.tk_popup(e.x_root, e.y_root)
            finally: report_menu.grab_release()
        report_txt.bind("<Button-3>", _show_menu)
